from pathlib import Path
from playwright.sync_api import sync_playwright
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'visual-output-mobile510-part4'; OUT.mkdir(exist_ok=True)
css='\n'.join((ROOT/'src'/f).read_text() for f in [
  'styles.css','design-system.css','product-system-v33.css','product-controls-v40.css','foundation-v24.css',
  'forms-v24.css','setup.css','booking-v30.css','mobile-app-v510.css','mobile-app-v510-part3.css','mobile-app-v510-part4.css'
])
head=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>{css}\n*{{box-sizing:border-box}} body{{margin:0;background:var(--surface-canvas);font-family:var(--font-ui);color:var(--ink-strong)}} button,input,textarea{{font:inherit}} .qa{{padding:12px 12px 92px;min-height:100vh}} .ld-shell{{display:block;height:auto;overflow:visible}} .ld-main{{display:block;height:auto;overflow:visible}} .ld-page-inner{{padding:0!important;max-width:none!important}} .ld-mobile-tabbar{{display:grid!important}} </style></head><body>'''
app_wrap=lambda content: head+f'''<div class="ld-shell has-mobile-tabbar"><main class="ld-main"><div class="ld-page"><div class="ld-page-inner"><main class="qa">{content}</main></div></div></main><nav class="ld-mobile-tabbar"><button class="ld-mobile-tabbar-item"><span class="ld-mobile-tabbar-icon">⌂</span><span>Início</span></button><button class="ld-mobile-tabbar-item"><span class="ld-mobile-tabbar-icon">□</span><span>Agenda</span></button><button class="ld-mobile-tabbar-item"><span class="ld-mobile-tabbar-icon">○</span><span>Clientes</span></button><button class="ld-mobile-tabbar-item"><span class="ld-mobile-tabbar-icon">◇</span><span>WhatsApp</span></button><button class="ld-mobile-tabbar-item is-active"><span class="ld-mobile-tabbar-icon">•••</span><span>Mais</span></button></nav></div></body></html>'''
settings='''<div class="settings-page"><div class="card custom-domains-card"><div class="cardHeader custom-domains-header"><div><div><h2 class="cardTitle">Domínio personalizado</h2><p class="cardDesc">Use até 5 endereços próprios com HTTPS automático.</p></div></div><span class="domain-security-pill">✓ DNS verificado</span></div><div class="cardBody custom-domains-body"><div class="domain-add-row"><div class="domain-input-wrap"><span>https://</span><input class="input" value="agenda.studioaurora.com.br"></div><button class="btn btnPrimary">Conectar domínio</button></div><div class="domain-list" style="margin-top:10px"><article class="domain-item"><div class="domain-item-head"><div><div class="domain-name-line"><strong>agenda.studioaurora.com.br</strong><span class="domain-status active">✓ Ativo</span><span class="domain-primary">★ Principal</span></div><span class="domain-meta">Verificado hoje às 09:32</span></div><div class="domain-actions"><button class="icon-btn">↗</button><button class="btn">Principal</button></div></div></article></div></div></div><div class="settings-grid"><div class="settings-column"><div class="card"><div class="cardHeader settings-card-header"><div><h2 class="cardTitle">Identidade visual</h2><p class="cardDesc">Personalize a aparência do seu espaço.</p></div></div><div class="cardBody"><div class="form-stack"><div class="input-group"><label class="label">Nome do Espaço</label><input class="input" value="Studio Aurora"></div><div class="input-group"><label class="label">Logo</label><div class="settings-logo-field"><div class="settings-logo-preview">A</div><div class="settings-logo-controls"><div class="settings-logo-actions"><button class="btn">Trocar logo</button><button class="icon-btn">×</button></div><p class="form-help">PNG, JPG ou WebP.</p></div></div></div><div class="form-actions"><button class="btn btnPrimary">Salvar Alterações</button></div></div></div></div></div><div class="settings-column"><div class="card security-settings-card"><div class="cardHeader settings-card-header"><div><h2 class="cardTitle">Segurança</h2><p class="cardDesc">Proteção da sua conta e sessões.</p></div></div><div class="cardBody security-settings-body"><section class="security-settings-section"><div class="security-settings-section-head"><div class="security-settings-heading"><div class="security-settings-icon">🔒</div><div><strong>Senha</strong><span>Atualize sua senha de acesso.</span></div></div></div><button class="btn">Alterar senha</button></section><section class="security-settings-section"><div class="security-settings-section-head"><div class="security-settings-heading"><div class="security-settings-icon">✓</div><div><strong>Verificação em duas etapas</strong><span>Proteção adicional por WhatsApp.</span></div></div></div><button class="btn">Configurar</button></section></div></div><div class="card"><div class="cardHeader"><h2 class="cardTitle">Assinatura</h2><span class="status-badge status-success">Ativa</span></div><div class="cardBody"><div class="settings-subscription-summary"><div class="settings-subscription-head"><div><span>Plano atual</span><strong>Assinatura</strong><small>Status: ACTIVE</small></div><span class="billing-plan-mark">ANUAL</span></div><p>Acesso válido até: <strong>17/08/2027</strong></p></div><p class="billing-note">Renovação por um novo checkout.</p></div></div><div class="card"><div class="cardHeader"><h2 class="cardTitle">Histórico de Faturas</h2></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Data</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody><tr><td>17/08/2026</td><td>R$ 598,80</td><td><span class="status-badge status-success">Pago</span></td><td><a class="table-link">Comprovante</a></td></tr><tr><td>17/08/2025</td><td>R$ 598,80</td><td><span class="status-badge status-success">Pago</span></td><td><a class="table-link">Comprovante</a></td></tr></tbody></table></div></div></div></div></div>'''
referral='''<section class="referral-page"><header class="referral-hero"><div><span class="eyebrow">Indique e economize</span><h1>Seu trabalho abre portas. Sua indicação também.</h1><p>Quem chega pelo seu link recebe 10% na primeira compra. Depois do pagamento confirmado, você recebe 10% para a próxima renovação.</p></div><div class="referral-reward"><strong>20%</strong><span>disponível na próxima renovação</span></div></header><div class="referral-metrics"><article><span>Cliques convertidos</span><strong>8</strong><small>12 cadastros iniciados</small></article><article><span>Economia das indicadas</span><strong>R$ 479,04</strong><small>somente pagamentos confirmados</small></article><article><span>Limite por renovação</span><strong>30%</strong><small>créditos excedentes ficam para depois</small></article></div><div class="referral-link-card"><div class="referral-link-copy">🔗<div><h2>Seu link pessoal</h2><p>Compartilhe com profissionais que realmente podem aproveitar a plataforma.</p></div></div><div class="referral-link-field"><input value="https://lashdesigner.app/r/aurora" readonly><button class="btn btnPrimary">Copiar link</button></div><p class="referral-rules">O benefício não vira saldo em dinheiro e nasce depois da confirmação do primeiro pagamento.</p></div></section>'''
setup=head+'''<div class="workspace-setup-layer"><section class="workspace-setup" style="--setup-primary:#8c4d66;--setup-secondary:#4f313e;--setup-background:#f7f1f3"><aside class="workspace-setup-aside"><div class="workspace-setup-mark">✦</div><div><span class="workspace-setup-eyebrow">Seu espaço começa aqui</span><h2>Seu espaço, do seu jeito.</h2></div><ol class="workspace-setup-progress"><li class="is-done"><span>✓</span><b>Caminho</b></li><li class="is-current"><span>2</span><b>Sua marca</b></li><li><span>3</span><b>Sua agenda</b></li><li><span>4</span><b>Seus serviços</b></li></ol><button class="workspace-setup-later">Configurar depois</button></aside><div class="workspace-setup-main"><div class="workspace-setup-step"><span class="workspace-setup-kicker">2 de 4 · identidade</span><h3>Vamos partir da sua marca.</h3><p>Escolha uma direção visual para o seu espaço.</p><div class="workspace-brand-grid"><div class="workspace-logo-upload"><button><strong>Enviar minha logo</strong><small>PNG, JPG ou WebP</small></button></div><div class="workspace-brand-fields"><label>Nome que suas clientes veem<input value="Studio Aurora"></label><label>Como sua marca deve parecer?<textarea>Elegante, acolhedora e profissional.</textarea></label><button class="workspace-analyze">✦ Analisar e sugerir paletas</button></div></div><div class="workspace-palette-grid"><button class="is-selected"><span class="workspace-palette-swatches"><i style="background:#8c4d66"></i><i style="background:#4f313e"></i><i style="background:#f7f1f3"></i></span><strong>Rosé profundo</strong><small>Elegante e acolhedor.</small></button><button><span class="workspace-palette-swatches"><i style="background:#6b5140"></i><i style="background:#2e2925"></i><i style="background:#faf6ef"></i></span><strong>Areia quente</strong><small>Natural e refinado.</small></button></div></div><footer class="workspace-setup-actions"><button class="workspace-back">Voltar</button><button class="workspace-next">Continuar →</button></footer></div></section></div></body></html>'''
booking=head+'''<main class="booking30"><div class="booking30-shell"><header class="booking30-topbar"><button class="booking30-brand"><span style="width:34px;height:34px;display:grid;place-items:center;border-radius:10px;background:#f3e7eb">A</span><span><strong>Studio Aurora</strong><small>Agendamento online</small></span></button><nav class="booking30-steps"><button class="is-complete"><span>01</span><strong>Serviço</strong></button><button class="is-current"><span>02</span><strong>Data</strong></button><button><span>03</span><strong>Horário</strong></button><button><span>04</span><strong>Confirmar</strong></button></nav><div class="booking30-step-count"><strong>2</strong><span>/ 4</span></div></header><div class="booking30-body"><section class="booking30-workspace"><div class="booking30-heading"><h1>Escolha o melhor dia para você.</h1><p>Mostramos apenas datas que ainda têm horários livres.</p></div><div class="booking30-mobile-summary"><span><small>Serviço</small><strong>Volume Brasileiro</strong></span><span><small>Duração</small><strong>90 min</strong></span></div><div class="booking30-date"><div class="dateScrollerWrapper"><div class="dateScrollerContainer"><button class="dateCard"><span class="dateCardWeek">ter</span><span class="dateCardDay">18</span><span class="dateCardMonth">ago</span></button><button class="dateCard selected"><span class="dateCardWeek">qua</span><span class="dateCardDay">19</span><span class="dateCardMonth">ago</span></button><button class="dateCard"><span class="dateCardWeek">qui</span><span class="dateCardDay">20</span><span class="dateCardMonth">ago</span></button><button class="dateCard"><span class="dateCardWeek">sex</span><span class="dateCardDay">21</span><span class="dateCardMonth">ago</span></button></div></div></div></section></div><footer class="booking30-footer"><span></span><small>Agendamento seguro · seus dados ficam protegidos</small></footer></div></main></body></html>'''
screens={'settings':app_wrap(settings),'referral':app_wrap(referral),'setup':setup,'booking':booking}
results=[]
with sync_playwright() as p:
  b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
  for name,html in screens.items():
    for w,h in [(390,844),(430,900),(768,900)]:
      pg=b.new_page(viewport={'width':w,'height':h})
      pg.set_content(html,wait_until='domcontentloaded')
      pg.wait_for_timeout(100)
      metrics=pg.evaluate('''() => ({sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth,body:document.body.scrollWidth})''')
      fail=metrics['sw']>metrics['cw']+2
      fn=f'{name}-{w}.png'; pg.screenshot(path=str(OUT/fn),full_page=False)
      results.append({'screen':name,'viewport':w,'fail':fail,**metrics,'shot':fn})
      pg.close()
  b.close()
(OUT/'matrix.json').write_text(json.dumps(results,indent=2,ensure_ascii=False))
print(json.dumps({'cases':len(results),'failures':sum(r['fail'] for r in results)},indent=2))
